// One message per sweep, not one per commitment. A desk that gets six separate
// WhatsApps about the same afternoon stops opening them.
const r = $input.first().json;
const lines = [];

if (r.escalations.length) {
  lines.push(`*${r.escalations.length} commitment(s) need you now*`);
  for (const e of r.escalations) {
    lines.push(`• ${e.customer} — ${e.what}\n  ${e.why}`);
  }
}

if (r.missed.length) {
  lines.push(`\n*${r.missed.length} missed*`);
  for (const m of r.missed) {
    lines.push(`• ${m.customer} — ${m.what} (was due ${m.deadline})`);
  }
}

const raisedHigh = r.raised.filter((x) => x.to === 'high');
if (raisedHigh.length) {
  lines.push(`\n${raisedHigh.length} moved to high risk: ${raisedHigh.map((x) => x.customer).join(', ')}`);
}

return [{ json: { text: lines.join('\n'), swept: r.swept, at: r.at } }];
